import{_ as e,o as s,c as t,a3 as i}from"./chunks/framework.BWzgKoSO.js";const r="/incomplete-weight-loss-guide/images/exercise/ex-squat.jpg",o="/incomplete-weight-loss-guide/images/exercise/ex-pushup-incline.jpg",g="/incomplete-weight-loss-guide/images/exercise/ex-pushup.jpg",n="/incomplete-weight-loss-guide/images/exercise/ex-glute-bridge.jpg",a="/incomplete-weight-loss-guide/images/exercise/ex-lunge.jpg",l="/incomplete-weight-loss-guide/images/exercise/ex-plank.jpg",c="/incomplete-weight-loss-guide/images/exercise/ex-calf-raise.jpg",m="/incomplete-weight-loss-guide/images/exercise/ex-goblet-squat.jpg",h="/incomplete-weight-loss-guide/images/exercise/ex-one-arm-row.jpg",_="/incomplete-weight-loss-guide/images/exercise/ex-db-bench.jpg",d="/incomplete-weight-loss-guide/images/exercise/ex-rdl.jpg",u="/incomplete-weight-loss-guide/images/exercise/ex-db-shoulder-press.jpg",x="/incomplete-weight-loss-guide/images/exercise/ex-farmers-walk.jpg",w="/incomplete-weight-loss-guide/images/exercise/ex-leg-press.jpg",b="/incomplete-weight-loss-guide/images/exercise/ex-lat-pulldown.jpg",j="/incomplete-weight-loss-guide/images/exercise/ex-cable-row.jpg",q="/incomplete-weight-loss-guide/images/exercise/ex-machine-chest-press.jpg",f="/incomplete-weight-loss-guide/images/exercise/ex-leg-curl.jpg",B="/incomplete-weight-loss-guide/images/exercise/ex-crunch.jpg",k="/incomplete-weight-loss-guide/images/exercise/ex-run-trail.jpg",P="/incomplete-weight-loss-guide/images/exercise/ex-dead-bug.jpg",A="/incomplete-weight-loss-guide/images/exercise/ex-side-plank.jpg",I="/incomplete-weight-loss-guide/images/exercise/ex-superman.jpg",C="/incomplete-weight-loss-guide/images/exercise/ex-step-up.jpg",G="/incomplete-weight-loss-guide/images/exercise/ex-single-glute-bridge.jpg",R="/incomplete-weight-loss-guide/images/exercise/ex-mountain-climber.jpg",M="/incomplete-weight-loss-guide/images/exercise/ex-walk-incline.jpg",T="/incomplete-weight-loss-guide/images/exercise/ex-runner-stretch.jpg",S="/incomplete-weight-loss-guide/images/exercise/ex-hip-flexor-stretch.jpg",O=JSON.parse('{"title":"第四部分　怎么练","description":"","frontmatter":{},"headers":[],"relativePath":"ch04-training.md","filePath":"ch04-training.md","lastUpdated":1793415983000}'),D={name:"ch04-training.md"};function E($,p,N,V,v,F){return s(),t("div",null,[...p[0]||(p[0]=[i('<h1 id="第四部分-怎么练" tabindex="-1">第四部分　怎么练 <a class="header-anchor" href="#第四部分-怎么练" aria-label="Permalink to &quot;第四部分　怎么练&quot;">​</a></h1><p>这一部分比前面短，因为练这件事，能做的其实不多，做对了就够。</p><h2 id="_4-1-什么算大基数" tabindex="-1">4.1　什么算大基数 <a class="header-anchor" href="#_4-1-什么算大基数" aria-label="Permalink to &quot;4.1　什么算大基数&quot;">​</a></h2><p>先把标准摆出来，别凭感觉。</p><p>按中国的成人体重判定标准：BMI 24 到 27.9 算超重，28 及以上算肥胖〔G8，A〕。腰围男性 ≥90 厘米、女性 ≥85 厘米，算中心型肥胖。</p><p>举个数：1.75 米的人，超重线是 73.5 公斤，肥胖线是 85.75 公斤。</p><p>腰围怎么量：站直，放松，别收腹，皮尺绕肚脐那一圈，呼气末读。同一个位置、同一个时间量，才有比较的意义。</p><p>但“大基数”这个词，我想给它换个说法。它真正问的不是你多重，是你的<strong>关节和心肺现在扛不扛得住跑跳</strong>。</p><p>所以判断用两个数：BMI 和腰围。BMI ≥28，或者比标准体重多出 20 公斤以上，就按大基数对待——先走，先下水，别急着跑。</p><h2 id="_4-2-大基数-先吃后练" tabindex="-1">4.2　大基数：先吃后练 <a class="header-anchor" href="#_4-2-大基数-先吃后练" aria-label="Permalink to &quot;4.2　大基数：先吃后练&quot;">​</a></h2><p>我自己的顺序：先游泳，掉了 10 斤左右，然后才转跑步。</p><p>为什么不一上来就跑？膝盖。</p><p>膝的问题从来不是一个原因，是三件叠加：体重压在上面，大腿和臀部的肌肉撑不住，跑量涨得比身体适应得快。三件里改一件，风险就下来一截；三件一起做，第二个月就得去挂号。</p><p><strong>起步分三档，对号入座。</strong></p><p><strong>第一档</strong>，BMI ≥30，或者很久没动过：走。每天 20 到 30 分钟，分成两段也行。有条件就下水游泳，水里膝关节的负担比陆地上小得多。每周 3 到 5 次。</p><p><strong>第二档</strong>，BMI 24 到 30，走了一个月不难受：走路照旧，加自重抗阻，每周 2 次，每次 15 分钟（动作见 4.4 的第二套）。有氧可以拉长到 40 分钟。</p><p><strong>第三档</strong>，能轻松走一小时了：开始跑，但用走跑交替——跑 1 分钟，走 2 分钟，重复 8 次。不追配速，追总时间。每周加量不超过上周的 10%。</p><p>这一档一档往上走的道理，跟指南说的“循序渐进”是一回事〔G1，A〕。</p><p><strong>再说一天的活动量。</strong></p><p>指南给的量是：中低强度有氧为主、抗阻为辅，有氧每周 150 到 300 分钟，每周 5 到 7 天，至少隔天一次；抗阻每周 2 到 3 天，每次 10 到 20 分钟；每周通过运动消耗 2000 千卡以上〔G1，A〕。</p><p>这个量不小。别把它当门槛，当方向。你现在一周只走三次，先走到五次，就是进步。</p><p>还有一条容易忽略的：每天静坐和被动看屏幕的时间控制在 2 到 4 小时以内，长期伏案的人每小时起来活动 3 到 5 分钟〔G1，A〕。这一条不花你任何意志力，收益比一次硬撑的训练大。</p><p><strong>第一周可以这么排</strong>（按第一档写，第二三档往上加）：</p><ul><li>周一：走 30 分钟</li><li>周二：休</li><li>周三：走 30 分钟 + 15 分钟自重（4.4 的 A 套）</li><li>周四：休</li><li>周五：走 30 分钟</li><li>周六：游泳或快走 40 分钟</li><li>周日：休，但别躺一天，出门走两趟</li></ul><p>一周动五次，加起来两个多小时，就到指南给的量了。</p><h2 id="_4-3-纯做有氧掉肌肉" tabindex="-1">4.3　纯做有氧掉肌肉 <a class="header-anchor" href="#_4-3-纯做有氧掉肌肉" aria-label="Permalink to &quot;4.3　纯做有氧掉肌肉&quot;">​</a></h2><p>这话对，但要加条件。</p><p>掉肌肉不是有氧的错，是四件事凑齐了才会明显：赤字开得太大、蛋白质吃不够、完全没有抗阻刺激、睡不够。</p><p>四件里你有三件，跑得再多也留不住肌肉。</p><p>指南在这件事上说得很清楚：减重过程中不能只看体重，要看体脂率和肌肉量的变化，目标是减少肌肉流失、维持肌肉量和基础代谢率〔G1，A〕。它给的手段就是抗阻运动每周 2 到 3 天。</p><p>我说句自己的：我 78 天里，抗阻一次都没系统练过。所以我掉的那 26.15 公斤里有多少是肌肉，我没有数据。这不是谦虚，这是我这本书的缺口，第四部分就是为了补它才写的。</p><h2 id="_4-4-抗阻最小方案" tabindex="-1">4.4　抗阻最小方案 <a class="header-anchor" href="#_4-4-抗阻最小方案" aria-label="Permalink to &quot;4.4　抗阻最小方案&quot;">​</a></h2><p>三套，每套 6 个动作，每周 2 到 3 次，隔天做。都不需要请教练。</p><p><strong>A 套：自重，家里一块垫子就够</strong></p><p>深蹲、俯卧撑（推墙起步，进阶到跪姿）、臀桥、弓步、平板支撑、提踵。</p><p>每个动作 2 组，8 到 12 次；平板支撑 20 到 40 秒。</p><p>下面每个动作配一张分解图，左格是起始，右格是做到位。照片来自 Free Exercise DB（公有领域），我按起止两帧拼在一起，标上了要点。</p><p>这几个动作，先把姿势做对，再谈组数。姿势错了，练的是伤。</p><p><strong>深蹲</strong></p><p><img src="'+r+'" alt="深蹲分解图：左图站直双脚与肩同宽，右图下蹲到大腿接近水平"></p><p>膝盖跟着脚尖方向，别往里扣；重心在脚掌中后段。起步就用椅子：站起来、坐下，不许用手撑。</p><p><strong>俯卧撑（两个版本）</strong></p><p><img src="'+o+'" alt="上斜俯卧撑分解图"></p><p><img src="'+g+'" alt="标准俯卧撑分解图"></p><p>身体成一条线，臀别塌。推墙或手撑桌子是上斜版，撑得越高越省力；能做到十个标准俯卧撑再往上加难度。</p><p><strong>臀桥</strong></p><p><img src="'+n+'" alt="臀桥分解图"></p><p>用屁股发力，不是用腰挺起来。顶到髋、肩、膝一条线就停，别往上翻腰。</p><p><strong>弓步</strong></p><p><img src="'+a+'" alt="弓步分解图"></p><p>前膝不超过脚尖太多，后膝垂直往地面去。站不稳就扶墙，别硬撑。</p><p><strong>平板支撑</strong></p><p><img src="'+l+'" alt="平板支撑分解图"></p><p>腰别塌，宁可缩短时间，也别撑着塌腰。撑不住就跪姿，跪着撑一分钟比塌腰撑三十秒强。</p><p><strong>提踵</strong></p><p><img src="'+c+'" alt="提踵分解图"></p><p>慢慢落，落下去那两秒才是关键。踮到最高停一下再放。</p><p><strong>B 套：一对哑铃（各 10 到 15 公斤，或一个壶铃）</strong></p><p>高脚杯深蹲、单臂划船、哑铃卧推、罗马尼亚硬拉、肩上推、负重走。每个 3 组，8 到 12 次。</p><p><strong>高脚杯深蹲</strong></p><p><img src="'+m+'" alt="高脚杯深蹲分解图"></p><p>重物抱在胸前，蹲的时候胸别往前扑，膝跟着脚尖方向。</p><p><strong>单臂划船</strong></p><p><img src="'+h+'" alt="单臂划船分解图"></p><p>一手撑椅子，背保持平直；肘往后拉到腰侧，别耸肩、别甩身体。这个动作伤了肩，要养很久。</p><p><strong>哑铃卧推</strong></p><p><img src="'+_+'" alt="哑铃卧推分解图"></p><p>下到胸两侧，推到手臂伸直但不锁死。没有凳子的，躺在地板上做，肘碰到地面就起。</p><p><strong>罗马尼亚硬拉</strong></p><p><img src="'+d+'" alt="罗马尼亚硬拉分解图"></p><p>靠屈髋把重物沿大腿往下放，背始终平直，感觉大腿后侧拉开就起身。别追着让重物触地——硬拉弓背是腰伤最常见的一幕。</p><p><strong>肩上推</strong></p><p><img src="'+u+'" alt="肩上推分解图"></p><p>从肩高往上推，别用腰后仰借力。坐着做能逼掉一部分借力。</p><p><strong>负重走</strong></p><p><img src="'+x+'" alt="负重走分解图"></p><p>两手各提一个重物，站直往前走，肩不歪、腰不塌。走 30 到 60 秒算一组，这个动作练的是核心和握力，比看上去累。</p><p><strong>C 套：健身房器械</strong></p><p>腿举、高位下拉、坐姿划船、胸推、腿弯举、卷腹。每个 3 组，10 到 12 次。</p><p>器械的好处是轨迹固定，不容易做错；坏处是重量加得太快，人容易只推得动前半程。</p><p><strong>腿举</strong></p><p><img src="'+w+'" alt="腿举分解图"></p><p>脚踩踏板与肩同宽，下到大腿接近胸口，蹬起时膝盖别锁死。</p><p><strong>高位下拉</strong></p><p><img src="'+b+'" alt="高位下拉分解图"></p><p>宽握，先让肩胛往下沉，再拉到上胸。别靠身体后仰去拽。</p><p><strong>坐姿划船</strong></p><p><img src="'+j+'" alt="坐姿划船分解图"></p><p>坐稳，先收肩胛再拉，拉到腹部，别用腰往后仰。</p><p><strong>胸推（器械）</strong></p><p><img src="'+q+'" alt="器械胸推分解图"></p><p>握把在胸两侧，推到手臂伸直，肩别耸。</p><p><strong>腿弯举</strong></p><p><img src="'+f+'" alt="腿弯举分解图"></p><p>慢慢屈膝把滚垫拉过来，放回去的那两三秒才是重点。</p><p><strong>卷腹</strong></p><p><img src="'+B+'" alt="卷腹分解图"></p><p>只起肩背，腰不离地。别用手拉脖子——脖子疼的人九成是这么来的。</p><p><strong>30 分钟版</strong>：热身 5 分钟，六个动作按顺序做 3 轮（每轮之间歇 60 到 90 秒），最后拉伸 5 分钟。</p><p><strong>15 分钟版</strong>：只做三个动作——一个蹲（腿）、一个推（胸肩）、一个拉（背），每个 3 组。时间不够的时候，做这三个比不做强太多。</p><p><strong>三条原则：</strong></p><p>重量选到最后一两次有点吃力、但动作不变形。变形的重量不算数。</p><p>组间歇够，别赶。你要的是刺激，不是心率。</p><p>关节疼就停，肌肉酸可以继续。这条分不清的人最容易受伤。</p><h2 id="_4-5-小基数" tabindex="-1">4.5　小基数 <a class="header-anchor" href="#_4-5-小基数" aria-label="Permalink to &quot;4.5　小基数&quot;">​</a></h2><p>BMI 24 以下、腰围正常的人，重点该从“减重”换成“改体型”。</p><p>做法：抗阻每周 3 次，有氧 2 次，缺口开小一点，300 到 500 千卡。</p><p>这个阶段最常见的情况是体重不动，裤腰在动。别急着看秤，看照片和腰围。</p><h2 id="_4-6-有氧怎么选-还有那些零碎的动" tabindex="-1">4.6　有氧怎么选，还有那些零碎的动 <a class="header-anchor" href="#_4-6-有氧怎么选-还有那些零碎的动" aria-label="Permalink to &quot;4.6　有氧怎么选，还有那些零碎的动&quot;">​</a></h2><p><strong>关节负担从低到高排</strong>：游泳、椭圆机 → 骑车 → 快走 → 慢跑 → 跳绳和高强度间歇。</p><p>按你现在的体重选，不是按别人的推荐选。80 公斤的人和 55 公斤的人，能承受的不是一回事。</p><p><strong>每天 6000 步</strong>是膳食指南给普通成年人的基本量〔G2，A〕。减重期往上加到 8000 到 12000 更好。走路这件事的好处是它不占时间——通勤、打电话、饭后十分钟，都能算进去。</p><p><strong>爬楼有个诀窍</strong>：上去爬，下来坐电梯。上楼的负荷是往上推，下楼是刹车，膝盖最怕的是刹车〔C〕。</p><p><strong>别小看零碎的动</strong>：站着打电话、饭后走十分钟、地铁早下一站。一天多走三千步，不占你一分钟额外时间，也不吃你的意志力。</p><p>练这件事，最值钱的不是强度，是不停。</p><h2 id="_4-7-跑步到底怎么跑" tabindex="-1">4.7　跑步到底怎么跑 <a class="header-anchor" href="#_4-7-跑步到底怎么跑" aria-label="Permalink to &quot;4.7　跑步到底怎么跑&quot;">​</a></h2><p>跑步的技术，吵了几十年。能落到地上的其实就三条：步频别太低，落脚别伸到身体前面，量别加太快。剩下的那些——前脚掌还是后脚跟、胳膊摆多少度、要不要上碳板鞋——要么证据不硬，要么跟减重没关系。</p><p><strong>先说步频。</strong></p><p>步频是一分钟落多少步。新手跑起来常常 150 到 160，专业选手常在 180 上下，于是“180”这个数就被传成了标准。它不是标准。</p><p>有研究让跑者把步频提高 5% 到 10%，髋、膝的关节负荷和下肢冲击都降下来了，步幅也跟着缩短〔R15，B〕。注意被支持的那句话是“比你现在的步频快一点”，不是“必须跑到 180”。</p><p>怎么用：数你现在三十秒落多少步，乘二，再往上加一成。150 的加到 165 左右就够，别一步跳到 180，改了步频又改姿势，身体同时适应两件事，最容易伤。</p><p><strong>再说落脚。</strong></p><p>跑步圈吵得最凶的是前脚掌还是后脚跟落地。有一项系统综述把五十三项研究收在一起看：改成前脚掌落地，膝盖的屈曲幅度和髌股关节的应力确实低了，但负荷挪到了踝关节和小腿的跖屈肌上；跑步经济性没有改善的证据；至于受伤风险，现有研究几乎都是回顾性的，缺前瞻性证据，关系定不下来。作者的结论很干脆：对一个没受伤的、习惯后脚跟落地的人，不建议改〔R16，B〕。</p><p>所以不用刻意改，也别信“改了姿势就能跑更快”这种话。但有一件事值得改——落脚点别伸得太靠前。</p><p>脚落在骨盆底下那一下，膝盖是弯的，冲击由肌肉吸收；脚伸出去老远再落地，膝盖几乎是直的，冲击直接传给关节。这个区别在慢动作里看得一清二楚。</p><p>自查：让家人拿手机从侧面拍你跑十秒，慢放，看落地点在骨盆前面还是骨盆底下。在前面一大截的，就是步幅太大，先收小。</p><p><strong>量怎么加。</strong></p><p>“每周加量不超过 10%”这句话你肯定听过。它没有研究证明 10% 是那个神奇数字，属于经验法则〔C〕。但“突然翻倍”确实是新手受伤最常见的原因，膝盖、胫骨、跟腱都挨这一刀。</p><p>我的做法更保守：连续两周跑完都舒服，第三周才加。加完那周有点酸是正常的，疼到走路不舒服，就退回去。</p><p>大体重的人，先走跑交替：跑一分钟，走两分钟，重复八次。把总时长当目标，配速先别看。等这套能连着做四十分钟不难受，再谈纯跑。指南给的方向本来也是中低强度有氧为主、循序渐进〔G1，A〕。</p><p><img src="'+k+'" alt="跑步姿势：上坡用小步快频，下坡屈膝减速，落脚别伸到身体前面"></p><h2 id="_4-8-二区心率-一个被说烂了的概念" tabindex="-1">4.8　二区心率，一个被说烂了的概念 <a class="header-anchor" href="#_4-8-二区心率-一个被说烂了的概念" aria-label="Permalink to &quot;4.8　二区心率，一个被说烂了的概念&quot;">​</a></h2><p>先说一个容易踩的坑：“二区”在两套体系里不是一个东西。</p><p>做耐力研究的人常用三区模型：一区在第一个乳酸阈以下，二区在两个乳酸阈之间，三区在第二个阈值以上。他们关心的是强度怎么分布——精英耐力选手大部分时间待在一区，少量时间扎在三区，中间那一块反而不多，所以叫“极化训练”〔R17，B〕。</p><p>手表和教练说的五区是另一套，按最大心率的百分比切，二区大约 60% 到 70%。中文跑圈说“跑二区”“二区有氧”，多数指的是这一套，也就是“轻松、能说话”那一档。</p><p>所以有人跟你说“要多跑二区”，你可以先问一句：你说的是三区模型的二区，还是五区的二区。问清楚，能省掉一个月的糊涂。</p><p>这本书里说的二区，按五区那个意思：轻松有氧，能说话。</p><p><strong>这条线怎么定。</strong></p><p>最好用的是官方口径。《肥胖症诊疗指南（2024年版）》把中等强度定在最大心率的 50% 到 70%〔G1，A〕，跟五区的二区基本重合，直接拿来用就行。</p><p>最大心率得估。最常见的是 220 减年龄，这个公式误差不小；研究给的替代方案是 208 减 0.7 乘年龄，在更大的样本里拟合得更好〔R18，B〕。但它仍然是估的，个体差十下很正常。</p><p>真想要精确，只有一条路：跑一次递增负荷测试，把实际最大心率测出来。那要设备和场地，多数人不需要。</p><p>再给一个更专业的坐标：第一乳酸阈大约在血乳酸 2 毫摩尔每升的位置，第二乳酸阈大约 4 毫摩尔每升〔R19，B〕。三区模型那两条线就是它们。测过乳酸的人用这套数；没测过，看下一条。</p><p><strong>最实用的办法：说话测试。</strong></p><p>能整句说完、不喘断，就是中等强度；只能说短句、得换气，就偏上了；说不出话，那是高强度〔R20，B〕。这个方法在心脏康复里用了几十年，不要设备，误差比公式小。</p><p>所以你要是戴着手表却懒得算：跑起来，试着说一整句话，或者背一句诗。能顺顺当当说完，就在二区；说到一半要喘，过线了。</p><p><strong>算一遍。</strong></p><p>四十岁，最大心率按 208 减 0.7×40＝180。指南那条中等强度线是 50% 到 70%，也就是 90 到 126。</p><p>用 220 减年龄算，四十岁也是 180，巧了；五十岁就不一样了，220 版给 170，208 版给 173。差三下不算多，可你的整个区间跟着挪。</p><p>手表读数跟你算出来的对不上，多半是三件事：最大心率用的是默认值、手环心率在跑动时滞后、表带没戴紧。</p><p><strong>八成和两成。</strong></p><p>平时做有氧，八成放在能说话那一档，两成留给喘的时候——比如一周跑四次，三次轻松，一次稍快。这不是法律，是让你别把每次跑都跑成考试。</p><h2 id="_4-9-呼吸-能说的和不能说的" tabindex="-1">4.9　呼吸：能说的和不能说的 <a class="header-anchor" href="#_4-9-呼吸-能说的和不能说的" aria-label="Permalink to &quot;4.9　呼吸：能说的和不能说的&quot;">​</a></h2><p>网上有很多“三吸两呼”“两吸一呼”的口诀，说得像有讲究。我去找了研究，能找到的是动物身上呼吸节律和步频的耦合，拿来推人的跑步呼吸，不够；人体上专门比较固定呼吸节律和自然呼吸的研究，我没找到像样的〔C〕。</p><p>所以这一节我只说三件事。</p><p>第一，别数呼吸。呼吸跟着强度走，是身体自己调的。你刻意数，注意力反而从姿势和路面上挪开了。</p><p>第二，鼻子吸、嘴呼，或者全程用嘴，都行。天冷、空气干的时候用鼻子吸舒服一点，这是体感，不是研究结论〔C〕。</p><p>第三，把呼吸当仪表，别当任务。跑起来能不能说完一整句话——这就是你的强度表，比任何口诀都准〔R20，B〕。喘到说不出话，降下来；一路轻松，可以再加一点。</p><p>至于跑步时侧腹疼，常见说法是“呼吸节奏错了”。这个说法我没找到过硬证据；能确认的诱因主要是刚吃完就跑，以及膈肌和内脏韧带的牵拉〔C〕。实操就一句：饭后至少等一个半小时再跑。</p><h2 id="_4-10-再补几个动作" tabindex="-1">4.10　再补几个动作 <a class="header-anchor" href="#_4-10-再补几个动作" aria-label="Permalink to &quot;4.10　再补几个动作&quot;">​</a></h2><p>4.4 那三套是骨架，够你把大肌群练起来。这一节补八个更细的，都能在家做，不用器械。</p><p><strong>死虫</strong>——练核心稳定，重点是腰不塌。仰卧，双手朝上，双腿抬起屈髋屈膝各九十度，对侧的手和腿慢慢伸直再收回，腰始终贴地。</p><p><img src="'+P+'" alt="死虫分解图：左图手脚抬起、腰贴地，右图对侧手脚伸直但不塌腰"></p><p><strong>侧平板</strong>——侧腰和髋外侧。肘撑地，身体成一条线，髋别往下掉。撑不住就把下面的膝盖跪地。</p><p><img src="'+A+'" alt="侧平板分解图：左图肘撑地侧卧屈膝，右图撑起成一条线"></p><p><strong>俯卧背伸</strong>——背部和腰。趴着，手腿同时抬离地面一点点，停两秒，慢慢放下。别抬到腰疼，这不是比谁抬得高。</p><p><img src="'+I+'" alt="俯卧背伸分解图：左图趴平，右图手腿微微抬离地面"></p><p><strong>登台阶</strong>——大体重的人用它代替弓步，膝盖压力小。踩上台阶，后脚跟发力站直，再慢慢下来。台阶高度到膝盖下面一点就够。</p><p><img src="'+C+'" alt="登台阶分解图：左图一脚踩上台，右图站直并提膝"></p><p><strong>单腿臀桥</strong>——臀桥的进阶。一条腿伸直抬起，另一条腿的脚跟踩地顶髋。腰别代偿，顶到肩、髋、膝一条线就停。</p><p><img src="'+G+'" alt="单腿臀桥分解图：左图一条腿抬起，右图用支撑腿顶髋"></p><p><strong>登山跑</strong>——有氧加核心，心率上得快。撑地，两腿交替往胸口提。BMI 高的时候先别做，手腕和腰吃不消。</p><p><img src="'+R+'" alt="登山跑分解图：左图撑地把一腿提到胸前，右图换腿"></p><p><strong>快走和坡度走</strong>——最被低估的一项。跑步机坡度调到 5% 到 10%，速度放慢一点，心率一样上去，膝盖的负担比跑小得多。走的时候别死抓扶手，那是把体重卸给机器了。</p><p><img src="'+M+'" alt="坡度走示意图：把坡度调到 5% 到 10%，速度放慢，别抓扶手"></p><p><strong>跑后拉伸</strong>——小腿和髋前侧。跑完趁身体热着做，每个动作三十秒，慢慢呼，别弹震。</p><p><img src="'+T+'" alt="跑后拉伸分解图：左图弓步下压拉后腿髋前侧，右图屈髋拉前腿后侧"></p><p><img src="'+S+'" alt="髋前侧拉伸分解图：左图单膝跪地，右图重心前移"></p><p>这些动作的照片都来自 Free Exercise DB，公有领域，可以随便用〔S2〕。我把每个动作的起止两帧拼成一张，标了要点；动作本身没改，也不是我本人示范。</p><hr><p>下一部分给一个能直接照着做的东西：30 天。</p>',180)])])}const U=e(D,[["render",E]]);export{O as __pageData,U as default};
